import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { MapPin, Calendar, ArrowRight, X } from "lucide-react";
import { projects } from "../../data/content";
import ImagePlaceholder from "../ui/ImagePlaceholder";
import AnimatedSection from "../ui/AnimatedSection";
import Badge from "../ui/Badge";

export default function Projects() {
  const [selected, setSelected] = useState(null);

  return (
    <section id="projects" className="bg-charcoal-50 section-pad">
      <div className="max-w-7xl mx-auto px-6 lg:px-10">
        {/* Header */}
        <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-6 mb-14">
          <div>
            <AnimatedSection variant="fadeUp">
              <span className="eyebrow mb-4 block">Featured Projects</span>
            </AnimatedSection>
            <AnimatedSection variant="fadeUp" delay={0.1}>
              <h2 className="font-display text-[clamp(2.2rem,4vw,3.2rem)] leading-[1.12]">
                Delivered at Scale.{" "}
                <em className="text-blue-800 not-italic">Built to Last.</em>
              </h2>
            </AnimatedSection>
          </div>
          <AnimatedSection variant="fadeUp" delay={0.15} className="max-w-sm">
            <p className="text-charcoal-500 text-sm leading-relaxed">
              Click any project to read the full case study — challenge, solution, and measurable impact.
            </p>
          </AnimatedSection>
        </div>

        {/* Projects grid */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
          {projects.map((proj, i) => (
            <AnimatedSection key={proj.id} variant="fadeUp" delay={i * 0.1}>
              <ProjectCard proj={proj} onOpen={() => setSelected(proj)} />
            </AnimatedSection>
          ))}
        </div>
      </div>

      {/* Modal */}
      <AnimatePresence>
        {selected && (
          <ProjectModal proj={selected} onClose={() => setSelected(null)} />
        )}
      </AnimatePresence>
    </section>
  );
}

function ProjectCard({ proj, onOpen }) {
  const [hovered, setHovered] = useState(false);

  return (
    <motion.div
      className="relative bg-white border border-charcoal-200 rounded-2xl overflow-hidden cursor-pointer group"
      whileHover={{ y: -5, boxShadow: "0 24px 60px rgba(11,61,143,0.12)" }}
      transition={{ duration: 0.3 }}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      onClick={onOpen}
    >
      {/* Image */}
      <div style={{ height: 240 }} className="relative overflow-hidden">
        <ImagePlaceholder
          image={proj.image}
          imagePlaceholderClass={proj.imagePlaceholderClass}
          imagePlaceholderText={proj.name}
          alt={proj.name}
          className="w-full h-full"
        >
          <motion.div
            className="absolute inset-0 bg-charcoal-950/30"
            animate={{ opacity: hovered ? 1 : 0 }}
            transition={{ duration: 0.3 }}
          />
          {/* Tags */}
          <div className="absolute top-4 left-4 flex gap-2">
            {proj.tags.map((tag) => (
              <Badge key={tag} variant="dark">{tag}</Badge>
            ))}
          </div>
          {/* Year */}
          <div className="absolute top-4 right-4">
            <Badge variant="dark">{proj.year}</Badge>
          </div>
        </ImagePlaceholder>
      </div>

      {/* Body */}
      <div className="p-6">
        <div className="flex items-center gap-1.5 text-charcoal-400 text-[11.5px] font-semibold mb-3">
          <MapPin size={11} />
          {proj.location}
        </div>
        <h3 className="font-display text-[1.2rem] text-charcoal-900 leading-snug mb-3 group-hover:text-blue-800 transition-colors">
          {proj.name}
        </h3>
        <p className="text-charcoal-500 text-[13px] leading-[1.7] line-clamp-2">
          {proj.challenge}
        </p>

        {/* Impact strip */}
        <div className="mt-5 pt-4 border-t border-charcoal-100 flex items-center justify-between">
          <div>
            <p className="text-[10px] font-bold tracking-[0.15em] uppercase text-blue-800 mb-1">Impact</p>
            <p className="text-[12.5px] text-charcoal-600 font-medium leading-snug">{proj.impact}</p>
          </div>
          <motion.div
            className="w-10 h-10 rounded-full bg-blue-800 flex items-center justify-center flex-shrink-0"
            animate={{ scale: hovered ? 1 : 0.85, opacity: hovered ? 1 : 0.5 }}
            transition={{ duration: 0.25 }}
          >
            <ArrowRight size={15} className="text-white" />
          </motion.div>
        </div>
      </div>
    </motion.div>
  );
}

function ProjectModal({ proj, onClose }) {
  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-charcoal-950/80 backdrop-blur-sm"
      onClick={onClose}
    >
      <motion.div
        initial={{ opacity: 0, scale: 0.94, y: 20 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.94, y: 20 }}
        transition={{ duration: 0.35, ease: [0.25, 0.46, 0.45, 0.94] }}
        className="relative bg-white rounded-2xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Image */}
        <div style={{ height: 280 }} className="relative overflow-hidden rounded-t-2xl">
          <ImagePlaceholder
            image={proj.image}
            imagePlaceholderClass={proj.imagePlaceholderClass}
            imagePlaceholderText={proj.name}
            alt={proj.name}
            className="w-full h-full"
          >
            <div className="absolute inset-0 bg-gradient-to-t from-charcoal-950/60 to-transparent" />
            <div className="absolute bottom-5 left-6 flex gap-2">
              {proj.tags.map((tag) => (
                <Badge key={tag} variant="dark">{tag}</Badge>
              ))}
            </div>
          </ImagePlaceholder>
        </div>

        {/* Close */}
        <motion.button
          whileHover={{ scale: 1.1 }}
          whileTap={{ scale: 0.9 }}
          onClick={onClose}
          className="absolute top-4 right-4 w-9 h-9 rounded-full bg-charcoal-950/60 backdrop-blur-sm flex items-center justify-center text-white"
        >
          <X size={16} />
        </motion.button>

        {/* Content */}
        <div className="p-8">
          <div className="flex items-center gap-4 mb-4">
            <div className="flex items-center gap-1.5 text-charcoal-400 text-[12px] font-semibold">
              <MapPin size={12} />
              {proj.location}
            </div>
            <div className="flex items-center gap-1.5 text-charcoal-400 text-[12px] font-semibold">
              <Calendar size={12} />
              {proj.year}
            </div>
          </div>

          <h2 className="font-display text-[1.7rem] text-charcoal-900 leading-snug mb-7">{proj.name}</h2>

          <div className="space-y-5">
            {[
              { label: "Challenge", text: proj.challenge, color: "text-red-700 bg-red-50 border-red-100" },
              { label: "Solution", text: proj.solution, color: "text-blue-800 bg-blue-50 border-blue-100" },
              { label: "Impact", text: proj.impact, color: "text-emerald-700 bg-emerald-50 border-emerald-100" },
            ].map(({ label, text, color }) => (
              <div key={label} className={`rounded-xl p-5 border ${color.split(" ").slice(1).join(" ")}`}>
                <p className={`text-[10px] font-bold tracking-[0.18em] uppercase mb-2 ${color.split(" ")[0]}`}>
                  {label}
                </p>
                <p className="text-charcoal-700 text-[14px] leading-[1.75]">{text}</p>
              </div>
            ))}
          </div>

          <motion.button
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.97 }}
            onClick={() => {
              onClose();
              setTimeout(() => document.getElementById("contact")?.scrollIntoView({ behavior: "smooth" }), 300);
            }}
            className="mt-8 w-full flex items-center justify-center gap-2 bg-blue-800 text-white py-3.5 rounded-xl font-bold text-sm hover:bg-blue-900 transition-colors"
          >
            Discuss a Similar Project
            <ArrowRight size={15} />
          </motion.button>
        </div>
      </motion.div>
    </motion.div>
  );
}
